-- 单元6 > 任务5 使用表单
-- ═══════════════════════════════════════════════════════════════

-- 1143: 表单标签(form)与input类型(text/password/radio/checkbox/submit/reset)
UPDATE knowledge_nodes SET content = '## 表单标签 `<form>`\n\n### 基本结构\n```html\n<form action="提交地址" method="提交方式">\n  <!-- 表单控件放在这里 -->\n</form>\n```\n| 属性 | 说明 |\n|------|------|\n| `action` | 表单数据提交到的URL |\n| `method` | 提交方式：`GET`（数据显示在URL中）或 `POST`（隐藏数据） |\n\n## `<input>` 常见类型\n\n| type值 | 控件样式 | 说明 |\n|------|------|------|\n| `text` | 单行文本框 | 输入文字 |\n| `password` | 密码框（输入显示●●●） | 输入密码 |\n| `radio` | 单选按钮 ○ | 一组中只能选一个（name相同） |\n| `checkbox` | 复选框 ☑ | 可多选 |\n| `submit` | 提交按钮 | 点击提交表单 |\n| `reset` | 重置按钮 | 清空所有输入 |\n| `button` | 普通按钮 | 配合JavaScript使用 |\n\n### 表单示例\n```html\n<form action="login.php" method="POST">\n  用户名：<input type="text" name="username"><br>\n  密码：<input type="password" name="password"><br>\n  性别：\n    <input type="radio" name="gender" value="male"> 男\n    <input type="radio" name="gender" value="female"> 女<br>\n  爱好：\n    <input type="checkbox" name="hobby" value="sports"> 运动\n    <input type="checkbox" name="hobby" value="music"> 音乐<br>\n  <input type="submit" value="登录">\n  <input type="reset" value="重置">\n</form>\n```\n\n### key属性\n- `name`：控件名称（提交时的键名）\n- `value`：控件值（提交时的值）\n- `placeholder`：输入提示文字\n\n> 考试重点：掌握text/password/radio/checkbox/submit/reset六种input类型。' WHERE id = 1143;

-- 1144: 多行文本框(textarea)与下拉列表(select)
UPDATE knowledge_nodes SET content = '## 文本框与下拉列表\n\n### 多行文本框 `<textarea>`\n```html\n<textarea name="intro" rows="5" cols="40" placeholder="请输入个人简介...">\n默认显示的文字\n</textarea>\n```\n| 属性 | 说明 |\n|------|------|\n| `rows` | 可见行数 |\n| `cols` | 可见列数（字符宽度） |\n| `placeholder` | 输入提示 |\n- 与`<input type="text">`的区别：textarea支持**多行输入**\n\n### 下拉列表 `<select>`\n```html\n<select name="city">\n  <option value="beijing">北京</option>\n  <option value="shanghai" selected>上海</option>\n  <option value="chengdu">成都</option>\n</select>\n```\n| 属性 | 说明 |\n|------|------|\n| `selected` | 默认选中该项 |\n| `multiple` | 允许多选（加在select标签上） |\n\n### 表单对比总结\n| 控件 | 标签 | 使用场景 |\n|------|------|------|\n| 文本框 | `<input type="text">` | 短文本（用户名/邮箱） |\n| 密码框 | `<input type="password">` | 密码输入 |\n| 单选 | `<input type="radio">` | 互斥选择（性别/是否） |\n| 多选 | `<input type="checkbox">` | 多选（爱好/权限） |\n| 下拉 | `<select>` | 选项多时节省空间（省市） |\n| 多行文本 | `<textarea>` | 长文本（简介/留言） |\n| 按钮 | `<button>` 或 `<input type="submit">` | 提交/确认操作 |\n\n> 考试重点：textarea用于多行文本，select用于下拉选项。' WHERE id = 1144;

-- 1145: 多媒体标签(audio/video)
UPDATE knowledge_nodes SET content = '## 多媒体标签\n\n### 音频标签 `<audio>`\n```html\n<audio controls>\n  <source src="music.mp3" type="audio/mpeg">\n  您的浏览器不支持audio标签\n</audio>\n```\n| 属性 | 说明 |\n|------|------|\n| `controls` | 显示播放控件（播放/暂停/音量） |\n| `autoplay` | 自动播放（浏览器可能阻止） |\n| `loop` | 循环播放 |\n\n### 视频标签 `<video>`\n```html\n<video controls width="640" height="360">\n  <source src="video.mp4" type="video/mp4">\n  您的浏览器不支持video标签\n</video>\n```\n| 属性 | 说明 |\n|------|------|\n| `controls` | 显示播放控件 |\n| `width/height` | 播放器大小 |\n| `poster` | 视频加载前的封面图片 |\n\n### 支持的多媒体格式\n| 类型 | 推荐格式 |\n|------|------|\n| 音频 | MP3、WAV、OGG |\n| 视频 | MP4、WebM、OGV |\n\n### 示例\n```html\n<!-- 音频播放器 -->\n<audio controls loop>\n  <source src="bgm.mp3" type="audio/mpeg">\n</audio>\n\n<!-- 视频播放器 -->\n<video controls width="800" poster="cover.jpg">\n  <source src="tutorial.mp4" type="video/mp4">\n</video>\n```\n\n> 考试考点：audio用于插入音频，video用于插入视频。两者均为HTML5新增标签。' WHERE id = 1145;

SELECT '=== Content填充完成 ===' AS '';
SELECT COUNT(*) AS filled_count FROM knowledge_nodes WHERE subject_id = 5 AND content IS NOT NULL AND content != '';
SELECT COUNT(*) AS empty_count FROM knowledge_nodes WHERE subject_id = 5 AND (content IS NULL OR content = '');
